"""Legacy-compatible Meridian CRM RBAC permission check."""

_VALID_ACTIONS = frozenset({"READ", "CREATE", "UPDATE", "DELETE", "EXPORT"})


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether ``user`` may perform ``action`` on ``record``."""
    if action not in _VALID_ACTIONS:
        return False

    role_id = user.get("ROLE_ID", "")

    matching_row = None
    for row in role_rows:
        if (
            row.get("role_id", "") == role_id
            and row.get("object", "") == object
            and row.get("action", "") == action
        ):
            matching_row = row
            break

    if matching_row is None:
        return False

    # DELETE requires a record that is not already soft-deleted.
    # A blank or missing CHAR(1) boolean has legacy value "N".
    if action == "DELETE" and record.get("DEL_FLG", "") not in ("", "N"):
        return False

    # ADMIN bypasses scope only; the matching permission row remains mandatory.
    if role_id == "ADMIN":
        return True

    scope = matching_row.get("scope", "")
    if scope == "ALL":
        return True
    if scope == "TEAM":
        return user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
    if scope == "OWN":
        return user.get("USR_ID", "") == record.get("OWNER_UID", "")

    return False
